// Deep-content pack for 1.2.23.2–16. Pure data: every family gains twelve
// further cohorts (to twenty-four), six rare specialists (to twelve), six named
// disturbances (to twelve), four goods (to eight), six relict layers (to
// twelve) and six field notes (to twelve in three tiers). Each family also
// declares two recurring cycles: a short harvest/regeneration rotation and a
// multi-decade event arc. The catalogue merges this into the one existing
// frontier ledger; nothing here runs per frame, per tick or per tile.

const freeze = Object.freeze;
const species = (id, label, kind, cover, note) => freeze({ id, label, kind, cover, note });
const specialist = (id, label, kind, note) => freeze({ id, label, kind, note });
const hazard = (id, label, trigger, effect) => freeze({ id, label, trigger, effect });
const good = (id, label, value, annual, note) => freeze({ id, label, value, annual, note });
const note = (tier, id, label, detail, goal, at, goalLabel, reward = {}) => freeze({
    id, label, detail, goal, at, goalLabel, tier,
    reward: freeze({
        gold: 0, morale: 0, food: 0, wood: 0, stone: 0,
        legitimacy: 0, relation: 0, military: 0, magic: 0, corruption: 0,
        charter: false, ...reward,
    }),
});
const cycle = (id, label, detail, period, phaseLabels, harvestPhase, regenerationPhase, reward) => freeze({
    id, label, detail, period, phaseLabels: freeze(phaseLabels),
    harvestPhase, regenerationPhase, reward: freeze({ ...reward }),
});
const family = value => freeze({
    species: freeze(value.species),
    specialists: freeze(value.specialists),
    hazards: freeze(value.hazards),
    goods: freeze(value.goods),
    relics: freeze(value.relics),
    journal: freeze(value.journal),
    cycles: freeze(value.cycles),
});

